/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #0d0d0f;
  --bg-secondary: #141416;
  --bg-card: #1a1a1e;
  --bg-elevated: #222228;
  --border: #2a2a32;
  --accent: #e8c547;
  --accent-dim: #b89a2e;
  --accent-glow: rgba(232, 197, 71, 0.15);
  --text-primary: #f0f0f2;
  --text-secondary: #8a8a96;
  --text-muted: #55555f;
  --red: #e84747;
  --green: #47e8a0;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow: 0 4px 24px rgba(0,0,0,0.5);
  --shadow-lg: 0 8px 48px rgba(0,0,0,0.7);
  --transition: 0.2s ease;
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.6;
  overflow-x: hidden;
}

a { text-decoration: none; color: inherit; }
img { display: block; max-width: 100%; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul { list-style: none; }

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

/* ===== UTILITY ===== */
.container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.badge {
  display: inline-block; padding: 3px 10px; border-radius: 100px;
  font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase;
}
.badge--accent { background: var(--accent); color: #0d0d0f; }
.badge--red { background: var(--red); color: #fff; }
.badge--ghost { background: transparent; border: 1px solid var(--border); color: var(--text-secondary); }
.section-header { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 28px; }
.section-header h2 { font-size: 22px; font-weight: 700; letter-spacing: -0.02em; }
.view-all {
  font-size: 13px; color: var(--accent); font-weight: 600;
  display: flex; align-items: center; gap: 4px; transition: gap var(--transition);
}
.view-all:hover { gap: 8px; }
.view-all::after { content: '→'; }

/* ===== ANNOUNCEMENT BAR ===== */
.announcement-bar {
  background: var(--accent);
  color: #0d0d0f;
  text-align: center;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.01em;
}
.announcement-bar a { text-decoration: underline; }

/* ===== NAV ===== */
.nav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(13,13,15,0.85);
  backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border);
}
.nav__inner {
  display: flex; align-items: center; gap: 32px;
  height: 64px;
}
.nav__logo {
  font-size: 20px; font-weight: 800; letter-spacing: -0.04em;
  color: var(--text-primary); white-space: nowrap;
}
.nav__logo span { color: var(--accent); }
.nav__links {
  display: flex; gap: 28px; flex: 1;
}
.nav__links a {
  font-size: 14px; font-weight: 500; color: var(--text-secondary);
  transition: color var(--transition); white-space: nowrap;
}
.nav__links a:hover { color: var(--text-primary); }
.nav__actions { display: flex; align-items: center; gap: 16px; margin-left: auto; }
.nav__search {
  display: flex; align-items: center; gap: 8px;
  background: var(--bg-elevated); border: 1px solid var(--border);
  border-radius: var(--radius-sm); padding: 7px 12px;
  transition: border-color var(--transition);
}
.nav__search:focus-within { border-color: var(--accent); }
.nav__search input {
  background: none; border: none; outline: none;
  color: var(--text-primary); font-size: 13px; width: 180px;
}
.nav__search input::placeholder { color: var(--text-muted); }
.nav__icon-btn {
  width: 38px; height: 38px; border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  background: var(--bg-elevated); border: 1px solid var(--border);
  color: var(--text-secondary); font-size: 16px;
  transition: all var(--transition); position: relative;
}
.nav__icon-btn:hover { color: var(--text-primary); border-color: var(--text-muted); }
.cart-count {
  position: absolute; top: -4px; right: -4px;
  width: 16px; height: 16px; border-radius: 50%;
  background: var(--accent); color: #0d0d0f;
  font-size: 9px; font-weight: 800;
  display: flex; align-items: center; justify-content: center;
}

/* ===== HERO ===== */
.hero {
  min-height: 600px;
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 0; overflow: hidden;
  position: relative;
}
.hero__main {
  background: linear-gradient(135deg, #0d0d0f 0%, #1a1218 50%, #0d0d0f 100%);
  display: flex; align-items: center;
  padding: 80px 64px;
  position: relative; overflow: hidden;
}
.hero__main::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse 70% 70% at 80% 50%, rgba(232,197,71,0.08) 0%, transparent 70%);
}
.hero__content { position: relative; z-index: 1; max-width: 480px; }
.hero__eyebrow {
  display: flex; align-items: center; gap: 8px; margin-bottom: 20px;
}
.hero__dot { width: 8px; height: 8px; background: var(--accent); border-radius: 50%; animation: pulse 2s infinite; }
@keyframes pulse { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(1.3); } }
.hero__eyebrow span { font-size: 13px; font-weight: 600; color: var(--accent); letter-spacing: 0.08em; text-transform: uppercase; }
.hero__title {
  font-size: clamp(36px, 4vw, 56px); font-weight: 800;
  letter-spacing: -0.04em; line-height: 1.1;
  margin-bottom: 20px;
}
.hero__title em { font-style: normal; color: var(--accent); }
.hero__desc { font-size: 16px; color: var(--text-secondary); margin-bottom: 36px; max-width: 380px; }
.hero__actions { display: flex; gap: 12px; flex-wrap: wrap; }
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 24px; border-radius: var(--radius-sm);
  font-size: 14px; font-weight: 700; letter-spacing: 0.01em;
  transition: all var(--transition); white-space: nowrap;
}
.btn--primary {
  background: var(--accent); color: #0d0d0f;
}
.btn--primary:hover { background: #f0ce55; transform: translateY(-1px); box-shadow: 0 4px 20px rgba(232,197,71,0.35); }
.btn--ghost {
  background: transparent; color: var(--text-primary);
  border: 1px solid var(--border);
}
.btn--ghost:hover { border-color: var(--text-secondary); background: var(--bg-elevated); }
.hero__stats { display: flex; gap: 32px; margin-top: 48px; }
.hero__stat-num { font-size: 26px; font-weight: 800; letter-spacing: -0.03em; }
.hero__stat-label { font-size: 12px; color: var(--text-muted); margin-top: 2px; }

.hero__visual {
  background: var(--bg-secondary);
  display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr;
  gap: 2px;
}
.hero__img-cell {
  overflow: hidden; position: relative; cursor: pointer;
}
.hero__img-cell img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 0.4s ease;
}
.hero__img-cell:hover img { transform: scale(1.05); }
.hero__img-cell--large { grid-row: span 2; }
.hero__img-overlay {
  position: absolute; inset: 0; background: linear-gradient(to top, rgba(0,0,0,0.6) 0%, transparent 50%);
  display: flex; align-items: flex-end; padding: 16px; opacity: 0;
  transition: opacity var(--transition);
}
.hero__img-cell:hover .hero__img-overlay { opacity: 1; }
.hero__img-label { font-size: 13px; font-weight: 600; color: #fff; }

/* ===== BRAND STRIP ===== */
.brand-strip {
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 20px 0;
  overflow: hidden;
}
.brand-strip__track {
  display: flex; gap: 60px; align-items: center;
  animation: marquee 30s linear infinite;
  white-space: nowrap;
}
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
.brand-strip__item {
  font-size: 14px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--text-muted); flex-shrink: 0;
  transition: color var(--transition);
}
.brand-strip__item:hover { color: var(--text-secondary); }
.brand-strip__sep { color: var(--border); flex-shrink: 0; }

/* ===== SECTIONS ===== */
section { padding: 72px 0; }
section + section { border-top: 1px solid var(--border); }

/* ===== FEATURED PRODUCTS ===== */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition);
  display: flex; flex-direction: column;
}
.product-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-3px);
  box-shadow: var(--shadow);
}
.product-card__image-wrap {
  position: relative; overflow: hidden;
  aspect-ratio: 3/4; background: var(--bg-elevated);
}
.product-card__image-wrap img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 0.4s ease;
}
.product-card:hover .product-card__image-wrap img { transform: scale(1.06); }
.product-card__badges {
  position: absolute; top: 12px; left: 12px;
  display: flex; flex-direction: column; gap: 6px;
}
.product-card__wishlist {
  position: absolute; top: 12px; right: 12px;
  width: 32px; height: 32px; border-radius: 50%;
  background: rgba(13,13,15,0.7); backdrop-filter: blur(8px);
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; opacity: 0; transition: opacity var(--transition);
  border: 1px solid var(--border);
}
.product-card:hover .product-card__wishlist { opacity: 1; }
.product-card__wishlist:hover { background: rgba(13,13,15,0.9); color: var(--red); }
.product-card__quick-add {
  position: absolute; bottom: 0; left: 0; right: 0;
  background: rgba(13,13,15,0.9); backdrop-filter: blur(8px);
  border-top: 1px solid var(--border);
  padding: 12px; font-size: 13px; font-weight: 700;
  color: var(--accent); text-align: center;
  transform: translateY(100%); transition: transform 0.25s ease;
  letter-spacing: 0.03em;
}
.product-card:hover .product-card__quick-add { transform: translateY(0); }
.product-card__quick-add:hover { background: rgba(232,197,71,0.12); }
.product-card__body { padding: 14px 16px 16px; flex: 1; display: flex; flex-direction: column; }
.product-card__brand { font-size: 11px; font-weight: 700; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 4px; }
.product-card__name { font-size: 14px; font-weight: 600; color: var(--text-primary); margin-bottom: 8px; line-height: 1.4; flex: 1; }
.product-card__rating { display: flex; align-items: center; gap: 5px; margin-bottom: 10px; }
.product-card__stars { display: flex; gap: 2px; }
.product-card__stars span { color: var(--accent); font-size: 11px; }
.product-card__stars span.empty { color: var(--border); }
.product-card__review-count { font-size: 11px; color: var(--text-muted); }
.product-card__price { display: flex; align-items: baseline; gap: 8px; }
.product-card__price-current { font-size: 17px; font-weight: 800; color: var(--text-primary); }
.product-card__price-original { font-size: 13px; color: var(--text-muted); text-decoration: line-through; }
.product-card__price-save { font-size: 12px; font-weight: 700; color: var(--green); }

/* ===== DEALS SECTION ===== */
.deals-section { background: var(--bg-secondary); }
.deals-header { margin-bottom: 32px; }
.deals-timer {
  display: flex; align-items: center; gap: 12px;
  margin-top: 10px;
}
.deals-timer__label { font-size: 13px; color: var(--text-muted); font-weight: 600; }
.deals-timer__clock { display: flex; align-items: center; gap: 6px; }
.timer-block {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 6px 10px; text-align: center; min-width: 46px;
}
.timer-block__num { font-size: 20px; font-weight: 800; letter-spacing: -0.03em; color: var(--accent); display: block; }
.timer-block__label { font-size: 9px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); display: block; }
.timer-sep { font-size: 18px; font-weight: 800; color: var(--text-muted); }

.deals-grid {
  display: grid;
  grid-template-columns: 1.8fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 16px;
}
.deal-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); overflow: hidden;
  display: flex; flex-direction: column;
  transition: all var(--transition);
}
.deal-card:hover { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent-glow), var(--shadow); }
.deal-card--hero { grid-row: span 2; flex-direction: row; }
.deal-card__image {
  overflow: hidden; position: relative;
}
.deal-card--hero .deal-card__image { flex: 1; min-height: 300px; }
.deal-card:not(.deal-card--hero) .deal-card__image { aspect-ratio: 16/10; }
.deal-card__image img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s ease; }
.deal-card:hover .deal-card__image img { transform: scale(1.04); }
.deal-card__content { padding: 20px; display: flex; flex-direction: column; gap: 8px; }
.deal-card--hero .deal-card__content { justify-content: center; min-width: 240px; }
.deal-card__tag { font-size: 11px; font-weight: 700; color: var(--accent); text-transform: uppercase; letter-spacing: 0.08em; }
.deal-card__name { font-size: 17px; font-weight: 700; line-height: 1.35; }
.deal-card--hero .deal-card__name { font-size: 22px; }
.deal-card__pricing { display: flex; align-items: baseline; gap: 10px; margin-top: 4px; }
.deal-card__price { font-size: 22px; font-weight: 800; color: var(--text-primary); }
.deal-card--hero .deal-card__price { font-size: 30px; }
.deal-card__original { font-size: 15px; color: var(--text-muted); text-decoration: line-through; }
.deal-card__discount {
  display: inline-flex; align-items: center;
  background: rgba(232,71,71,0.15); color: var(--red);
  font-size: 12px; font-weight: 800; padding: 3px 8px; border-radius: 100px;
}
.deal-card__progress { margin-top: 8px; }
.deal-card__progress-label { display: flex; justify-content: space-between; font-size: 11px; color: var(--text-muted); margin-bottom: 6px; }
.deal-card__progress-bar {
  height: 4px; background: var(--border); border-radius: 2px; overflow: hidden;
}
.deal-card__progress-fill {
  height: 100%; background: linear-gradient(90deg, var(--accent-dim), var(--accent));
  border-radius: 2px; transition: width 1s ease;
}
.deal-card__cta {
  margin-top: 16px; padding: 11px 20px; background: var(--accent); color: #0d0d0f;
  border-radius: var(--radius-sm); font-size: 13px; font-weight: 800;
  text-align: center; transition: all var(--transition); display: block;
}
.deal-card__cta:hover { background: #f0ce55; transform: translateY(-1px); }
.deal-card:not(.deal-card--hero) .deal-card__cta {
  padding: 9px 16px; font-size: 12px; margin-top: 8px;
}

/* ===== CATEGORIES ===== */
.categories-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
}
.category-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-md); overflow: hidden;
  cursor: pointer; transition: all var(--transition);
  display: flex; flex-direction: column; align-items: center;
  padding: 24px 16px; gap: 12px; text-align: center;
}
.category-card:hover { border-color: var(--accent); background: var(--bg-elevated); transform: translateY(-2px); }
.category-card__icon { font-size: 32px; line-height: 1; }
.category-card__name { font-size: 13px; font-weight: 700; color: var(--text-primary); }
.category-card__count { font-size: 11px; color: var(--text-muted); }

/* ===== EDITORIAL ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}
.editorial-card {
  background: var(--bg-card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: all var(--transition);
}
.editorial-card:hover { transform: translateY(-3px); box-shadow: var(--shadow); border-color: var(--text-muted); }
.editorial-card--featured { grid-row: span 2; display: flex; flex-direction: column; }
.editorial-card__image { overflow: hidden; position: relative; }
.editorial-card--featured .editorial-card__image { flex: 1; min-height: 320px; }
.editorial-card:not(.editorial-card--featured) .editorial-card__image { aspect-ratio: 16/9; }
.editorial-card__image img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.editorial-card:hover .editorial-card__image img { transform: scale(1.04); }
.editorial-card__category-overlay {
  position: absolute; top: 16px; left: 16px;
}
.editorial-card__body { padding: 22px; }
.editorial-card--featured .editorial-card__body { padding: 26px; }
.editorial-card__meta { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.editorial-card__category { font-size: 11px; font-weight: 700; color: var(--accent); text-transform: uppercase; letter-spacing: 0.08em; }
.editorial-card__date { font-size: 11px; color: var(--text-muted); }
.editorial-card__title { font-size: 17px; font-weight: 700; line-height: 1.35; margin-bottom: 10px; }
.editorial-card--featured .editorial-card__title { font-size: 22px; }
.editorial-card__excerpt { font-size: 13px; color: var(--text-secondary); line-height: 1.6; margin-bottom: 16px; }
.editorial-card__read-more {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 13px; font-weight: 700; color: var(--accent);
  transition: gap var(--transition);
}
.editorial-card__read-more::after { content: '→'; transition: transform var(--transition); }
.editorial-card:hover .editorial-card__read-more { gap: 10px; }

/* ===== NEWSLETTER ===== */
.newsletter {
  background: linear-gradient(135deg, var(--bg-card) 0%, #1a1820 100%);
  border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
  padding: 64px 0;
}
.newsletter__inner {
  display: flex; align-items: center; justify-content: space-between; gap: 48px;
}
.newsletter__text { flex: 1; }
.newsletter__title { font-size: 28px; font-weight: 800; letter-spacing: -0.03em; margin-bottom: 8px; }
.newsletter__title span { color: var(--accent); }
.newsletter__desc { font-size: 15px; color: var(--text-secondary); }
.newsletter__form { flex: 0 0 420px; }
.newsletter__input-wrap {
  display: flex; gap: 0;
  background: var(--bg-elevated); border: 1px solid var(--border);
  border-radius: var(--radius-sm); overflow: hidden;
  transition: border-color var(--transition);
}
.newsletter__input-wrap:focus-within { border-color: var(--accent); }
.newsletter__input-wrap input {
  flex: 1; padding: 14px 16px; background: none; border: none; outline: none;
  color: var(--text-primary); font-size: 14px;
}
.newsletter__input-wrap input::placeholder { color: var(--text-muted); }
.newsletter__input-wrap button {
  padding: 14px 20px; background: var(--accent); color: #0d0d0f;
  font-size: 13px; font-weight: 800; border-left: 1px solid rgba(0,0,0,0.1);
  transition: background var(--transition); white-space: nowrap;
}
.newsletter__input-wrap button:hover { background: #f0ce55; }
.newsletter__trust { display: flex; gap: 20px; margin-top: 14px; }
.newsletter__trust-item { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--text-muted); }
.newsletter__trust-item span:first-child { color: var(--green); font-size: 14px; }

/* ===== FOOTER ===== */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 60px 0 32px;
}
.footer__grid {
  display: grid; grid-template-columns: 1.5fr 1fr 1fr 1fr; gap: 48px;
  margin-bottom: 48px;
}
.footer__brand-desc { font-size: 14px; color: var(--text-secondary); margin: 12px 0 20px; line-height: 1.7; }
.footer__socials { display: flex; gap: 10px; }
.footer__social {
  width: 36px; height: 36px; border-radius: var(--radius-sm);
  background: var(--bg-elevated); border: 1px solid var(--border);
  display: flex; align-items: center; justify-content: center;
  font-size: 16px; transition: all var(--transition);
}
.footer__social:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.footer__col-title { font-size: 13px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-primary); margin-bottom: 16px; }
.footer__col-links { display: flex; flex-direction: column; gap: 10px; }
.footer__col-links a { font-size: 14px; color: var(--text-secondary); transition: color var(--transition); }
.footer__col-links a:hover { color: var(--text-primary); }
.footer__bottom {
  border-top: 1px solid var(--border); padding-top: 24px;
  display: flex; align-items: center; justify-content: space-between;
}
.footer__copy { font-size: 13px; color: var(--text-muted); }
.footer__legal { display: flex; gap: 20px; }
.footer__legal a { font-size: 13px; color: var(--text-muted); transition: color var(--transition); }
.footer__legal a:hover { color: var(--text-secondary); }
.footer__payments { display: flex; gap: 8px; align-items: center; }
.footer__payment-icon {
  background: var(--bg-elevated); border: 1px solid var(--border);
  border-radius: 4px; padding: 3px 8px;
  font-size: 11px; font-weight: 700; color: var(--text-secondary);
}

/* ===== TOAST ===== */
.toast-container { position: fixed; bottom: 24px; right: 24px; z-index: 999; display: flex; flex-direction: column; gap: 10px; }
.toast {
  background: var(--bg-elevated); border: 1px solid var(--border);
  border-radius: var(--radius-md); padding: 14px 18px;
  display: flex; align-items: center; gap: 12px;
  box-shadow: var(--shadow-lg);
  animation: slideIn 0.3s ease; max-width: 320px;
}
@keyframes slideIn { from { opacity: 0; transform: translateX(40px); } to { opacity: 1; transform: translateX(0); } }
.toast__icon { font-size: 20px; }
.toast__text { font-size: 14px; font-weight: 600; }
.toast__sub { font-size: 12px; color: var(--text-secondary); margin-top: 2px; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1100px) {
  .products-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card--hero { grid-column: span 2; flex-direction: row; }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card--featured { grid-column: span 2; flex-direction: row; }
  .editorial-card--featured .editorial-card__image { min-width: 340px; }
  .footer__grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}

@media (max-width: 768px) {
  .hero { grid-template-columns: 1fr; min-height: auto; }
  .hero__main { padding: 48px 24px; }
  .hero__visual { display: none; }
  .nav__links { display: none; }
  .nav__search { display: none; }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card--hero { flex-direction: column; }
  .editorial-card--featured { flex-direction: column; grid-column: span 1; }
  .editorial-card--featured .editorial-card__image { min-width: unset; min-height: 220px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .newsletter__inner { flex-direction: column; gap: 28px; }
  .newsletter__form { flex: 0 0 auto; width: 100%; }
  .footer__grid { grid-template-columns: 1fr 1fr; gap: 28px; }
  .footer__bottom { flex-direction: column; gap: 16px; text-align: center; }
}

